// Signed in: newest of users/{uid}/assigned and top-level assigned (the
// coach skill still writes top-level until it moves to per-user paths).
async function fetchLatestAssigned() {
  const cols = [window.__collection(window.__db, 'assigned')];
  if (window.__auth && window.__auth.currentUser()) cols.unshift(window.__auth.userCol('assigned'));
  const at = v => (v && v.toMillis ? v.toMillis() : v);
  let best = null;
  for (const col of cols) {
    let snap;
    try {
      snap = await window.__getDocs(window.__query(
        col, window.__orderBy('assignedFor', 'desc'), window.__limit(1)
      ));
    } catch (err) {
      // A failing per-user read must not block the top-level fallback.
      if (col.path === 'assigned') throw err;
      note('User workouts unavailable: ' + err.message);
      continue;
    }
    if (snap.empty) continue;
    const hit = { data: snap.docs[0].data(), id: snap.docs[0].id };
    if (!best || at(hit.data.assignedFor) > at(best.data.assignedFor)) best = hit;
  }
  return best;
}

